    alpha = np.random.uniform(0.4, 0.6)
    cluster_size = max(3, num_items // 4)
    for _ in range(4):
        indices = np.random.choice(num_items, size=cluster_size, replace=False)
        cluster_in = indices[new_solution[indices] == 0]
        cluster_out = indices[new_solution[indices] == 1]

        if len(cluster_in) > 0 and len(cluster_out) > 0:
            in_scores = (value1_lst[cluster_in] * alpha + value2_lst[cluster_in] * (1-alpha)) / weight_lst[cluster_in]
            out_scores = (value1_lst[cluster_out] * (1-alpha) + value2_lst[cluster_out] * alpha) / weight_lst[cluster_out]

            best_in = cluster_in[np.argmax(in_scores)]
            worst_out = cluster_out[np.argmin(out_scores)]

            if (current_weight - weight_lst[worst_out] + weight_lst[best_in]) <= capacity:
                new_solution[worst_out] = 0
                new_solution[best_in] = 1
                current_weight = current_weight - weight_lst[worst_out] + weight_lst[best_in]

    # Phase 2: Value-balancing perturbation
    for _ in range(5):
        indices = np.random.choice(num_items, size=min(6, num_items), replace=False)
        for idx in indices:
            if new_solution[idx] == 1:
                balance_factor = (value1_lst[idx] - value2_lst[idx]) / (np.max(value1_lst) + np.max(value2_lst))
                if balance_factor > 0.4 and np.random.random() < 0.4:
                    if current_weight - weight_lst[idx] <= capacity:
                        new_solution[idx] = 0
            else:
                balance_factor = (value2_lst[idx] - value1_lst[idx]) / (np.max(value1_lst) + np.max(value2_lst))
                if balance_factor > 0.4 and np.random.random() < 0.5 and (current_weight + weight_lst[idx]) <= capacity:
                    new_solution[idx] = 1

    # Phase 3: Adaptive objective-driven flips
    for _ in range(3):
        indices = np.random.choice(num_items, size=min(4, num_items), replace=False)
        for idx in indices:
            if new_solution[idx] == 1:
                if (value1_lst[idx] + value2_lst[idx]) < (np.mean(value1_lst) + np.mean(value2_lst)) and np.random.random() < 0.3:
                    if current_weight - weight_lst[idx] <= capacity:
                        new_solution[idx] = 0
            else:
                if (value1_lst[idx] + value2_lst[idx]) > (np.mean(value1_lst) + np.mean(value2_lst)) and np.random.random() < 0.4:
                    if (current_weight + weight_lst[idx]) <= capacity:
                        new_solution[idx] = 1

    # Phase 4: Feasibility-aware knapsack optimization
    if current_weight > capacity:
        excess_weight = current_weight - capacity
        sorted_out_items = np.where(new_solution == 1)[0]
        sorted_out_items = sorted_out_items[np.argsort((value1_lst[sorted_out_items] + value2_lst[sorted_out_items]) / weight_lst[sorted_out_items])]

        for idx in sorted_out_items:
            if excess_weight <= 0:
                break
            if new_solution[idx] == 1:
                new_solution[idx] = 0
                excess_weight -= weight_lst[idx]

    return new_solution
